const KEY='medrelay-guardian-v1';
const seed=()=>({incident:true,temperature:5.4,inventory:[{id:1,name:'Insulin Glargine · Demo',qty:18,volume:6,reviewed:true},{id:2,name:'Semaglutide · Demo',qty:11,volume:4,reviewed:true},{id:3,name:'Amoxicillin Suspension · Demo',qty:14,volume:3,reviewed:false}],transfer:null,log:[{time:'14:00',title:'Power outage reported',detail:'Demo incident opened for refrigerator RX-01.'},{time:'14:08',title:'Temperature reading recorded',detail:'5.4°C · Simulated reading. No sensor connected.'}]});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed()}catch{state=seed()}let filter='',capacityOnly=false,selectedStorage='';
const facilities=buildUnifiedFacilities();facilities.forEach(f=>{const v=state.networkVolumes?.[f.id];if(Number.isFinite(v)&&v>=0)f.capacity=v;f.storageSuitable=state.networkSuitability?.[f.id]===true});
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const count=()=>state.inventory.reduce((a,x)=>a+x.qty,0),volume=()=>state.inventory.filter(x=>x.reviewed).reduce((a,x)=>a+x.volume,0);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Browser storage unavailable; keep this page open.')}}
function log(title,detail){state.log.push({time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),title,detail});save()}
let timer;function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(timer);timer=setTimeout(()=>t.style.display='none',4000)}
function heading(eyebrow,title,desc,actions=''){return `<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${desc}</p></div><div class="actions">${actions}</div></div>`}
const btn=(text,action,primary=false)=>`<button ${primary?'class="primary"':''} data-action="${action}">${text}</button>`;
function assistant(){return `<div class="card assist"><div class="eyebrow">✧ ASSISTANT PREVIEW</div><h2>Your next best step</h2><p>${state.inventory.some(x=>!x.reviewed)?'Review missing product requirements before including those products in a storage request.':'Reviewed stock is ready for storage matching.'}</p><hr><h3>How matching works</h3><ul><li>Only reviewed stock is included.</li><li>Capacity must cover ${volume()} L of reviewed inventory.</li><li>A partner must accept before departure.</li></ul><div class="inline-note">This panel uses rules. Open the incident planner for a Bedrock-generated response when the server is connected.</div><a class="button" href="#inventory">Review inventory →</a><a class="button full" href="#response">Open incident planner →</a></div>`}
const pharmacyEquipment=[
{name:'Medication refrigerator RX-01',type:'Cooler',count:1,backup:'No backup power',holdover:'2 hours',basis:'Illustrative equipment scenario'},
{name:'Medication refrigerator RX-02',type:'Cooler',count:1,backup:'Battery backup',holdover:'4 hours',basis:'Illustrative equipment scenario'},
{name:'Portable medication cooler',type:'Cooler',count:2,backup:'Passive cooling',holdover:'6 hours each',basis:'Illustrative packing scenario'},
{name:'Medication freezer',type:'Freezer',count:1,backup:'No backup power',holdover:'Not configured',basis:'Requires equipment validation'},
{name:'Automated dispensing cabinet',type:'Dispensing',count:1,backup:'Not configured',holdover:'Not applicable',basis:''},
{name:'Pharmacy workstation',type:'Computer',count:3,backup:'UPS status unknown',holdover:'Not applicable',basis:''},
{name:'Label printer',type:'Printer',count:2,backup:'None recorded',holdover:'Not applicable',basis:''},
{name:'Barcode scanner',type:'Scanner',count:2,backup:'Not configured',holdover:'Not applicable',basis:''}
];
function overview(){const units=pharmacyEquipment.reduce((n,e)=>n+e.count,0),coolers=pharmacyEquipment.filter(e=>e.type==='Cooler').reduce((n,e)=>n+e.count,0);const nearest=[...facilities].filter(f=>f.available&&f.storageSuitable===true&&Number.isFinite(f.capacity)&&f.capacity>=volume()&&volume()>0).sort((a,b)=>a.miles-b.miles)[0];return networkSummary()+heading('PHARMACY AT A GLANCE','Outage overview.','Equipment, cooler holdover, and the next storage destination.',btn('Report outage','report',true))+nearestLocationCard()+`<div class="simple-status"><span class="pill amber">${state.incident?'Power outage active':'No active outage'}</span><span>Refrigerator RX-01 · Last reading <strong>${state.temperature.toFixed(1)}°C</strong> · Demo / manual data</span><button data-action="reading">Update reading</button></div><div class="stats"><div class="card"><span class="stat-label">Equipment in the pharmacy</span><div class="number">${units} <small>units</small></div><p class="footnote">${pharmacyEquipment.length} equipment types · Demo inventory</p></div><div class="card"><span class="stat-label">Coolers</span><div class="number">${coolers} <small>of ${units} units</small></div><p class="footnote">2 refrigerators + 2 portable coolers</p></div><div class="card"><span class="stat-label">Nearest pharmacy · Synthetic example</span><div class="number">${nearestNetworkPharmacy()?.miles.toFixed(1)||'—'} <small>miles · Demo</small></div><p class="footnote">${esc(nearestNetworkPharmacy()?.name||'No powered site')} · ${nearestNetworkPharmacy()?.minutes||'—'} min · Demo</p></div></div><div class="card"><div class="sectiontop"><div><h2>Equipment & cooler holdover</h2><p class="subtitle">All recorded machines, including quantities and cooler outage duration.</p></div><span class="pill grey">Sample inventory</span></div><div class="tablewrap"><table><thead><tr><th>EQUIPMENT / MACHINE</th><th>UNITS</th><th>TYPE</th><th>POWER / COOLING BACKUP</th><th>HOLDOVER AFTER OUTAGE</th></tr></thead><tbody>${pharmacyEquipment.map(e=>`<tr><td><strong>${e.name}</strong></td><td>${e.count}</td><td><span class="pill ${e.type==='Cooler'?'':'grey'}">${e.type}</span></td><td>${e.backup}</td><td><strong>${e.holdover}</strong>${e.basis?`<br><small>${e.basis}</small>`:''}</td></tr>`).join('')}</tbody></table></div><div class="inline-note">Holdover means the modeled duration within the required storage conditions after power loss. These sample values are not validated or safe-storage guarantees. Actual duration depends on the unit, ambient conditions, load, door openings, backup system, and product requirements. No live countdown is calculated.</div></div><div class="card full"><div class="sectiontop"><div><div class="eyebrow">TRANSFER PLANNING</div><h2 class="full">${nearest?'Nearest potential storage: '+esc(nearest.name):'No eligible storage candidate'}</h2></div>${nearest?`<span class="pill">${nearest.min} min · Demo</span>`:''}</div>${nearest?`<p class="subtitle">${nearest.miles.toFixed(1)} miles · ${nearest.capacity} L reported capacity for ${volume()} L of reviewed stock. This is the nearest eligible partner by demo distance, not simply the closest building.</p><div class="trip-breakdown"><div><small>Preparation & loading</small><strong>Not recorded</strong></div><div><small>Driving to destination</small><strong>${nearest.min} min · Demo</strong></div><div><small>Receiving handover</small><strong>Not recorded</strong></div><div><small>Total time with medicines</small><strong>Not yet determined</strong></div></div><p class="footnote">Driving time excludes preparation, loading, traffic changes, and handover. Check the real route and confirm acceptance before moving medicines.</p>${mapActions(nearest)}`:'<p class="subtitle">Review affected stock and partner capacity to identify a destination.</p>'}<div class="actions"><a class="button primary" href="#storage">View storage network →</a><a class="button" href="#response">Open incident planner</a></div></div>`}

function inventory(){return heading('AFFECTED STOCK','Review your inventory.','Fictional product lines. Review status is a demo workflow flag, not clinical validation.',btn('＋ Add product','add',true))+`<div class="card"><div class="toolbar"><input type="search" id="search" aria-label="Search inventory" placeholder="Search product names" value="${esc(filter)}"><a class="button primary" href="#storage">Find storage for reviewed stock →</a></div><div class="tablewrap"><table><thead><tr><th>PRODUCT</th><th>PACKAGES</th><th>VOLUME</th><th>REQUIREMENTS</th><th>ACTION</th></tr></thead><tbody>${state.inventory.filter(x=>x.name.toLowerCase().includes(filter.toLowerCase())).map(x=>`<tr><td><strong>${esc(x.name)}</strong><br><small>Fictional training inventory</small></td><td>${x.qty}</td><td>${x.volume} L</td><td><span class="pill ${x.reviewed?'':'amber'}">${x.reviewed?'Demo reviewed':'Needs review'}</span></td><td><button data-review="${x.id}">${x.reviewed?'Undo review':'Review record'}</button></td></tr>`).join('')||'<tr><td colspan="5">No matching products.</td></tr>'}</tbody></table></div><div class="inline-note">All demo products use the same fictional refrigerated storage category. Real products require exact formulation, approved source documents, storage conditions, and excursion history.</div></div>`}
function facilityAddress(f){return state.facilityAddresses?.[f.id]||''}
function mapsUrl(f){const destination=facilityAddress(f).trim();if(!destination)return '';let url='https://www.google.com/maps/dir/?api=1&travelmode=driving&destination='+encodeURIComponent(destination);if(state.originAddress?.trim())url+='&origin='+encodeURIComponent(state.originAddress.trim());return url}
function mapActions(f){return `<div class="map-address"><p>${facilityAddress(f)?esc(facilityAddress(f)):'Address not set · Fictional demo partner'}</p><div class="actions"><button data-address="${f.id}">${facilityAddress(f)?'Edit address':'Add address'}</button>${mapsUrl(f)?`<a class="button" href="${esc(mapsUrl(f))}" target="_blank" rel="noopener noreferrer" aria-label="Driving directions to ${esc(f.name)} in Google Maps">Directions in Google Maps ↗</a>`:'<button disabled>Directions in Google Maps ↗</button>'}</div></div>`}
function storage(){let eligible=facilities.filter(f=>!capacityOnly||(f.available&&f.storageSuitable===true&&Number.isFinite(f.capacity)&&f.capacity>=volume()));let list=eligible.filter(f=>!selectedStorage||f.id===selectedStorage);return heading('PARTNER NETWORK','Find a place for your stock.','Open driving directions in Google Maps to see route distance and estimated travel time.')+`<div class="cols"><div class="card"><div class="sectiontop"><h2>Storage partners</h2><span class="pill">${volume()} L requested</span></div><div class="inline-note"><strong>Starting point:</strong> ${esc(state.originAddress||'Choose your starting point in Google Maps')} <button data-action="origin">Set starting address</button><p>Partners are fictional. Add an address before opening directions. Google Maps calculates the route; storage suitability still requires confirmation.</p></div><div class="storage-picker"><label class="fieldlabel" for="storage-network-select">Storage network / partner</label><select id="storage-network-select"><option value="">All storage partners</option>${[...facilities].sort((a,b)=>a.miles-b.miles).map(f=>`<option value="${f.id}" ${selectedStorage===f.id?'selected':''}>${f.name} — ${f.miles.toFixed(1)} miles${!f.available||!f.storageSuitable||!Number.isFinite(f.capacity)||f.capacity<volume()?' · Unconfirmed / insufficient capacity':''}</option>`).join('')}</select><p class="footnote">Distances are illustrative demo estimates, not calculated from your starting address. Use Google Maps for actual route distance.</p></div><label class="check"><input type="checkbox" id="capacity" ${capacityOnly?'checked':''}> Show recently available partners with enough capacity</label>${list.map(f=>`<div class="facility"><div class="facility-head"><div><h3>${f.name}</h3><p>${f.miles.toFixed(1)} miles · Demo estimate · ${Number.isFinite(f.capacity)?f.capacity+' L recorded':'Volume not recorded'}</p></div><span class="pill ${f.available&&f.capacity?'':'grey'}">${f.available&&f.capacity?'Potential match':'Unconfirmed / unavailable'}</span></div><p>${f.power?'Power reported on':'Power outage'} · ${f.capacityPercent}% relative receiving capacity · ${f.updated}</p><button data-volume="${f.id}">${Number.isFinite(f.capacity)?'Update volume (L)':'Record volume (L)'}</button><label class="check"><input type="checkbox" data-suitability="${f.id}" ${f.storageSuitable?'checked':''}> Product-specific storage suitability reviewed · Demo flag</label>${mapActions(f)}<div class="actions"><button data-request="${f.id}" class="primary" ${!state.incident||!f.available||!f.storageSuitable||!Number.isFinite(f.capacity)||f.capacity<volume()||volume()===0||state.transfer?'disabled':''}>Request storage · Demo</button><button data-detail="${f.id}">View details</button></div></div>`).join('')||'<p>No eligible facilities. Review inventory volume or show all partners.</p>'}${state.transfer?'<div class="inline-note">An existing transfer is in progress. <a href="#transfer">Manage transfer →</a></div>':''}${!state.incident?'<div class="inline-note">Report an incident before requesting storage.</div>':''}</div>${assistant()}</div>`}
function transfer(){let t=state.transfer;if(!t)return heading('COORDINATION','Your transfers.','Keep a record from storage request to handover.')+`<div class="card empty"><h2>No transfer yet</h2><p class="subtitle">Choose a suitable partner and request temporary storage.</p><a class="button primary" href="#storage">Find storage →</a></div>`;let f=facilities.find(x=>x.id===t.facility);return heading('TRANSFER TR-104','Coordinate the handover.',`Destination: ${f.name} · Demo workflow`)+`<div class="cols"><div class="card"><div class="sectiontop"><h2>${esc(t.status)}</h2><span class="pill">${t.volume} L · ${t.packages} packages</span></div>${t.status==='Requested'?`<p class="subtitle">This request is simulated. No facility has been contacted.</p>${btn('Simulate partner acceptance','accept',true)}`:t.status==='Accepted'?`<p class="subtitle">Partner acceptance simulated. Confirm each item before recording departure.</p>${['Product requirements and selected stock reviewed','Appropriate transport equipment and monitoring arranged','Receiving capacity and handover contact confirmed'].map((x,i)=>`<label class="check"><input data-check="${i}" type="checkbox" ${t.checks[i]?'checked':''}>${x}</label>`).join('')}<button class="primary" data-action="depart" ${t.checks.every(Boolean)?'':'disabled'}>Record departure · Demo</button>`:t.status==='In transit'?`<p class="subtitle">Record the receiving temperature and acknowledgment to complete this demo.</p><label class="check">Arrival temperature (°C) <input type="number" id="arrival" step="0.1" min="-100" max="100" value="5.2"></label>${btn('Record arrival & handover','arrive',true)}`:`<p>Handover recorded with a receiving temperature of ${t.arrival}°C.</p><div class="inline-note">Completion records custody only. Product usability remains a separate pharmacist assessment.</div>`}<div class="actions full">${btn('Export incident record','export')}</div></div><div class="card"><h2>Chain of custody</h2>${state.log.filter(x=>/request|accept|departure|handover/i.test(x.title)).map(x=>`<div class="log"><time>${esc(x.time)}</time><div><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p></div></div>`).join('')}<p class="footnote">Local prototype records are editable browser data, not an authenticated audit trail.</p></div></div>`}
function activity(){return heading('DOCUMENTATION','Incident activity.','A local history of actions in this demo.',btn('Export record','export')+btn('Reset demo','reset'))+`<div class="card">${[...state.log].reverse().map(x=>`<div class="log"><time>${esc(x.time)}</time><div><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p></div></div>`).join('')}</div>`}
function render(){let page=location.hash.slice(1)||'dashboard';if(!['dashboard','find','response','architecture','inventory','storage','transfer','activity'].includes(page))page='dashboard';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));document.querySelector('#crumb').textContent={dashboard:'Overview',find:'User',response:'Incident planner',architecture:'Architecture',inventory:'Inventory',storage:'Storage network',transfer:'Transfers',activity:'Incident log'}[page];app.innerHTML=({dashboard:overview,find:finderPage,response:responsePage,architecture:architecturePage,inventory,storage,transfer,activity})[page]();bind();if(window.applyRoleGate)window.applyRoleGate(page)}
function show(html){dialog.innerHTML=html;if(!dialog.open)dialog.showModal();bindMaps(dialog);dialog.querySelector('[data-close]')?.addEventListener('click',()=>dialog.close())}
function form(title,fields,submit){show(`<form><h2>${title}</h2>${fields}<div class="actions"><button class="primary" type="submit">Save</button><button type="button" data-close>Cancel</button></div></form>`);dialog.querySelector('form').onsubmit=e=>{e.preventDefault();submit(new FormData(e.target));dialog.close();render()}}
function action(a){if(a==='origin')form('Starting pharmacy address',`<label>Address<input name="address" maxlength="300" required value="${esc(state.originAddress||'')}" placeholder="Street, city, state, ZIP"></label>`,d=>{state.originAddress=String(d.get('address')).trim();save()});if(a==='plan'){location.hash='response'}if(a==='report')form('Report a power outage','<p class="subtitle">Starts a demo incident. No external notification is sent.</p><label>Current temperature (°C)<input name="temp" type="number" step="0.1" min="-100" max="100" required value="5.4"></label>',d=>{state.incident=true;state.temperature=Number(d.get('temp'));log('Power outage reported','Demo incident active. Latest manual reading recorded.');toast('Demo incident saved')});if(a==='reading')form('Record a temperature reading','<label>Temperature (°C)<input name="temp" type="number" min="-100" max="100" step="0.1" required></label>',d=>{state.temperature=Number(d.get('temp'));log('Temperature reading recorded',state.temperature+'°C · Manual demo entry.')});if(a==='add')form('Add a demo product','<label>Product name<input name="name" maxlength="100" required></label><label>Packages<input name="qty" type="number" min="1" max="100000" step="1" required></label><label>Total storage volume (L)<input name="volume" type="number" min="0.1" max="10000" step="0.1" required></label>',d=>{state.inventory.push({id:Date.now(),name:d.get('name'),qty:Number(d.get('qty')),volume:Number(d.get('volume')),reviewed:false});log('Inventory product added',String(d.get('name'))+' · Pending review.')});if(a==='accept'&&state.transfer?.status==='Requested'){state.transfer.status='Accepted';log('Partner acceptance simulated','No real facility has accepted this stock.');render()}if(a==='depart'&&state.transfer?.status==='Accepted'&&state.transfer.checks.every(Boolean)){state.transfer.status='In transit';log('Departure recorded','Demo stock released for transfer.');render()}if(a==='arrive'&&state.transfer?.status==='In transit'){const v=document.querySelector('#arrival');if(!v.checkValidity()||v.value===''){v.reportValidity();return}state.transfer.arrival=Number(v.value);state.transfer.status='Completed';log('Receiving handover recorded',v.value+'°C · Demo arrival. Product usability not determined.');render()}if(a==='export'){let blob=new Blob([JSON.stringify({...state,notice:'Fictional demo data. Not an authenticated clinical record.'},null,2)],{type:'application/json'});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='medrelay-demo-incident.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}if(a==='reset'){show('<h2>Reset demo data?</h2><p>Replaces this browser’s incident and inventory with the original fictional scenario.</p><div class="actions full"><button class="primary" id="reset-confirm">Reset demo</button><button data-close>Cancel</button></div>');dialog.querySelector('#reset-confirm').onclick=()=>{state=seed();facilities.forEach(f=>f.capacity=null);selectedStorage='';save();dialog.close();render();toast('Demo reset')}}}
function bind(){bindNearby();bindCommunity();bindContinuity();bindMaps(app);app.querySelector('#storage-network-select')?.addEventListener('change',e=>{selectedStorage=e.target.value;if(selectedStorage)capacityOnly=false;render()});app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));app.querySelector('#search')?.addEventListener('input',e=>{let pos=e.target.selectionStart;filter=e.target.value;render();let input=app.querySelector('#search');input.focus();input.setSelectionRange(pos,pos)});app.querySelector('#capacity')?.addEventListener('change',e=>{capacityOnly=e.target.checked;render()});app.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{let x=state.inventory.find(x=>x.id==b.dataset.review);if(x.reviewed){x.reviewed=false;log('Review status updated',x.name+' · Review removed.');render();return}show(`<h2>Review demo product</h2><p>${esc(x.name)}</p><div class="inline-note">This fictional product has no manufacturer documentation. Marking it reviewed only demonstrates the workflow.</div><button class="primary" id="confirm-review">Mark demo record reviewed</button> <button data-close>Cancel</button>`);dialog.querySelector('#confirm-review').onclick=()=>{x.reviewed=true;log('Demo product reviewed',x.name+' · Training flag only.');dialog.close();render()}});app.querySelectorAll('[data-request]').forEach(b=>b.onclick=()=>{let f=facilities.find(x=>x.id===b.dataset.request);if(state.transfer||!state.incident||!f.available||!f.storageSuitable||!Number.isFinite(f.capacity)||f.capacity<volume()||!volume())return;state.transfer={facility:f.id,volume:volume(),packages:state.inventory.filter(x=>x.reviewed).reduce((s,x)=>s+x.qty,0),items:state.inventory.filter(x=>x.reviewed).map(x=>({...x})),checks:[false,false,false],status:'Requested'};log('Storage request simulated',f.name+' · '+volume()+' L. No message sent.');location.hash='transfer'});app.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{let f=facilities.find(x=>x.id===b.dataset.detail);show(`<h2>${f.name}</h2><span class="pill">Fictional facility</span><p>${Number.isFinite(f.capacity)?f.capacity+' L recorded':'Volume not recorded'} · ${f.capacityPercent}% relative receiving capacity</p><p>${f.generator?'Backup power reported':'No backup power reported'} · Last update ${f.updated}</p>${mapActions(f)}<p class="subtitle">This demo assumes compatible refrigerated storage. A live system must verify exact conditions, authorization, capacity, and acceptance.</p><div class="actions full"><button data-close>Close</button></div>`)});app.querySelectorAll('[data-check]').forEach(c=>c.onchange=()=>{state.transfer.checks[Number(c.dataset.check)]=c.checked;save();app.querySelector('[data-action="depart"]').disabled=!state.transfer.checks.every(Boolean)})}
window.addEventListener('hashchange',render);render();

function bindMaps(container){container.querySelectorAll('[data-address]').forEach(b=>b.onclick=()=>{const f=facilities.find(x=>x.id===b.dataset.address);form('Address for '+f.name,`<p class="subtitle">Demo partner: enter the destination you want to explore. This does not verify that the location accepts medicines.</p><label>Destination address<input name="address" required maxlength="300" placeholder="Street, city, state, ZIP" value="${esc(facilityAddress(f))}"></label>`,d=>{state.facilityAddresses=state.facilityAddresses||{};state.facilityAddresses[f.id]=String(d.get('address')).trim();save();toast('Address saved. Open Google Maps for distance and travel time.')})})}
